"""invoice_validation.py

Pure invoice validation and event-sorting helpers for the synthetic ledger.

The module is intentionally dependency-free and side-effect-free: every function
accepts plain data (strings, ints, mappings, sequences) and returns a new value.
"""

from __future__ import annotations

import re
from typing import Any, Iterable, Mapping, Sequence

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

RECORD_ID_RE = re.compile(r"^R\d{6}$")
ACCOUNT_RE = re.compile(r"^A\d{2}$")
VALID_STATUSES = frozenset({"paid", "pending", "void", "refunded"})
NOTE_RE = re.compile(r"^[A-Za-z0-9 _.,;:()\-]+$")


# ---------------------------------------------------------------------------
# 1. Record identifier validation
# ---------------------------------------------------------------------------

def is_valid_record_id(record_id: str) -> bool:
    """Return True if record_id matches the canonical R###### format."""
    return isinstance(record_id, str) and bool(RECORD_ID_RE.fullmatch(record_id))


def record_id_number(record_id: str) -> int:
    """Extract the numeric portion of a record id, raising ValueError if invalid."""
    if not is_valid_record_id(record_id):
        raise ValueError(f"invalid record id: {record_id!r}")
    return int(record_id[1:])


def record_id_sort_key(record_id: str) -> tuple[int, str]:
    """Sort key for record ids: numeric order first, then lexical tie-break."""
    return (record_id_number(record_id), record_id)


# ---------------------------------------------------------------------------
# 2. Account validation
# ---------------------------------------------------------------------------

def is_valid_account(account: str) -> bool:
    """Return True if account matches the canonical A## format."""
    return isinstance(account, str) and bool(ACCOUNT_RE.fullmatch(account))


def account_number(account: str) -> int:
    """Extract the numeric portion of an account id."""
    if not is_valid_account(account):
        raise ValueError(f"invalid account: {account!r}")
    return int(account[1:])


def account_sort_key(account: str) -> tuple[int, str]:
    """Sort key for accounts: numeric order first, then lexical tie-break."""
    return (account_number(account), account)


